import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";

/** Object storage seam. Dev uses local disk; production swaps in S3/GCS with KMS encryption and presigned URLs. */
export interface FileStorage {
  put(key: string, data: Buffer): Promise<void>;
  get(key: string): Promise<Buffer>;
  delete(key: string): Promise<void>;
}

// Keys are generated by us as `<tenant uuid>/<file uuid>`. Anything else is refused, so a bug elsewhere can never
// turn into path traversal or cross-tenant reads.
const KEY = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
export const storageKey = (tenantId: string, fileId: string) => `${tenantId}/${fileId}`;
function assertKey(key: string) {
  if (!KEY.test(key)) throw new Error("Invalid storage key.");
}

export class LocalStorage implements FileStorage {
  constructor(private readonly root: string) {}
  private resolve(key: string) {
    assertKey(key);
    const full = path.resolve(this.root, key);
    if (!full.startsWith(path.resolve(this.root) + path.sep)) throw new Error("Invalid storage key.");
    return full;
  }
  async put(key: string, data: Buffer) {
    const full = this.resolve(key);
    await mkdir(path.dirname(full), { recursive: true, mode: 0o700 });
    await writeFile(full, data, { flag: "wx", mode: 0o600 }); // never overwrite
  }
  async get(key: string) {
    return readFile(this.resolve(key));
  }
  async delete(key: string) {
    await rm(this.resolve(key), { force: true });
  }
}

export class MemoryStorage implements FileStorage {
  readonly objects = new Map<string, Buffer>();
  async put(key: string, data: Buffer) {
    assertKey(key);
    if (this.objects.has(key)) throw new Error("exists");
    this.objects.set(key, data);
  }
  async get(key: string) {
    assertKey(key);
    const v = this.objects.get(key);
    if (!v) throw new Error("not found");
    return v;
  }
  async delete(key: string) {
    this.objects.delete(key);
  }
}
